import express from 'express';
import { auth, isHR } from '../middleware/auth.js';
import Notification from '../models/Notification.js';
import User from '../models/User.js';
import Course from '../models/Course.js';
import Blog from '../models/Blog.js';

const router = express.Router();

router.get('/', auth, async (req, res) => {
  const list = await Notification.find({ toUserId: req.user.userId }).sort({ createdAt: -1 }).limit(50);
  res.json(list);
});

router.patch('/:id/read', auth, async (req, res) => {
  await Notification.findOneAndUpdate({ _id: req.params.id, toUserId: req.user.userId }, { read: true });
  res.json({ ok: true });
});

