router.post('/courses/:slug/enroll', auth, async (req, res) => {
  const course = await Course.findOne({ slug: req.params.slug });
  if (!course) return res.status(404).json({ message: 'Course not found' });
  const user = await User.findById(req.user.userId);
  if (user.enrolledCourses.some((e) => e.courseId === course.slug)) return res.json({ message: 'Already enrolled' });
  if ((course.priceCoins || 0) > (user.skillCoins || 0)) return res.status(400).json({ message: 'Not enough Skill Coins' });
  user.skillCoins -= course.priceCoins || 0;
  user.enrolledCourses.push({ courseId: course.slug, enrolledAt: new Date() });
  await user.save();
  res.json({ message: 'Enrolled', coins: user.skillCoins });
});

